  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_waste_group_rule_area` (`normalized_area`),
  KEY `idx_waste_group_rule_active` (`is_active`,`normalized_area`)
) ENGINE=InnoDB AUTO_INCREMENT=32036 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS waste_daily_allocations`;
