  `source_row_number` int(11) NOT NULL DEFAULT 0,
  `reason_code` varchar(60) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_waste_import_event_issue` (`event_id`,`worksheet_name`,`source_row_number`,`reason_code`),
  KEY `idx_waste_import_event_issues_event` (`event_id`)
) ENGINE=InnoDB AUTO_INCREMENT=237 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS waste_import_events`;
CREATE TABLE `waste_import_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
