  `reason_code` varchar(60) DEFAULT NULL,
  `event_source` enum('legacy_manifest','live') NOT NULL DEFAULT 'live',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_waste_import_event_key` (`event_key`),
  KEY `idx_waste_import_events_created_outcome` (`created_at`,`outcome`),
  KEY `idx_waste_import_events_actor_created` (`actor_user_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=587 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS waste_import_manifests`;
CREATE TABLE `waste_import_manifests` (
  `file_sha256` char(64) NOT NULL,
  `dataset_sha256` char(64) NOT NULL,
  `original_name` varchar(255) NOT NULL,
  `row_count` int(11) NOT NULL,
  `imported_by` int(11) DEFAULT NULL,
  `imported_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`file_sha256`),
  UNIQUE KEY `unique_waste_import_dataset` (`dataset_sha256`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS waste_import_staging_rows`;
CREATE TABLE `waste_import_staging_rows` (
