  `collection_group_type` enum('phase','establishment') DEFAULT NULL,
  `reporting_period` varchar(255) DEFAULT NULL,
  `name_of_bioman` varchar(255) DEFAULT NULL,
  `households` varchar(100) DEFAULT NULL,
  `tuesday_factory_returnable_kg` decimal(10,2) NOT NULL DEFAULT 0.00,
  `comply_tue` varchar(50) DEFAULT NULL,
  `cd_processing` varchar(100) DEFAULT NULL,
  `wednesday_biowaste_kg` decimal(10,2) NOT NULL DEFAULT 0.00,
  `comply_wed` varchar(50) DEFAULT NULL,
  `thursday_factory_returnable_kg` decimal(10,2) NOT NULL DEFAULT 0.00,
  `friday_biowaste_kg` decimal(10,2) NOT NULL DEFAULT 0.00,
  `comply_fri` varchar(50) DEFAULT NULL,
  `saturday_hazard_waste_kg` decimal(10,2) NOT NULL DEFAULT 0.00,
  `residual_waste_kg` decimal(10,2) NOT NULL DEFAULT 0.00,
