  PRIMARY KEY (`record_fingerprint`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS waste_records`;
CREATE TABLE `waste_records` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `date` varchar(50) NOT NULL COMMENT 'Combined Month and Week (e.g., January Week 1)',
  `collection_date` date DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `phase_number` varchar(50) NOT NULL,
  `street` varchar(100) NOT NULL,
  `kilogram_of_waste` decimal(10,2) DEFAULT 0.00,
  `recyclable_kg` decimal(10,2) DEFAULT 0.00,
  `residual_kg` decimal(10,2) DEFAULT 0.00,
  `hazardous_kg` decimal(10,2) DEFAULT 0.00,
  `garbage_collector` varchar(100) DEFAULT NULL COMMENT 'Staff name from users table',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_by` varchar(100) DEFAULT NULL,
  `name_of_bioman` varchar(255) DEFAULT NULL,
  `households` varchar(100) DEFAULT NULL,
  `tuesday_factory_returnable_kg` decimal(10,2) DEFAULT 0.00,
  `comply_tue` varchar(50) DEFAULT NULL,
  `cd_processing` varchar(100) DEFAULT NULL,
  `wednesday_biowaste_kg` decimal(10,2) DEFAULT 0.00,
  `comply_wed` varchar(50) DEFAULT NULL,
  `thursday_factory_returnable_kg` decimal(10,2) DEFAULT 0.00,
  `friday_biowaste_kg` decimal(10,2) DEFAULT 0.00,
  `comply_fri` varchar(50) DEFAULT NULL,
  `saturday_hazard_waste_kg` decimal(10,2) DEFAULT 0.00,
  `residual_waste_kg` decimal(10,2) DEFAULT 0.00,
  `phase_date_label` varchar(255) DEFAULT NULL,
  `collection_group` varchar(255) DEFAULT NULL,
  `reporting_period` varchar(255) DEFAULT NULL,
  `collection_group_type` enum('phase','establishment') DEFAULT NULL,
  `record_fingerprint` char(64) DEFAULT NULL,
  `unclassified_waste_kg` decimal(10,2) DEFAULT 0.00,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_waste_records_fingerprint` (`record_fingerprint`),
  KEY `idx_waste_records_collection_date` (`collection_date`),
  KEY `idx_waste_records_active_collection_date` (`is_active`,`collection_date`),
  KEY `idx_waste_records_fingerprint` (`record_fingerprint`),
  KEY `idx_waste_records_date_group` (`collection_date`,`collection_group`,`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14481 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS waste_records_archive`;
CREATE TABLE `waste_records_archive` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `source_record_id` int(11) NOT NULL,
  `archived_by` int(11) DEFAULT NULL,
  `archived_at` datetime NOT NULL DEFAULT current_timestamp(),
  `retain_until` date DEFAULT NULL,
  `record_payload` longtext NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_archived_source_record` (`source_record_id`),
  KEY `idx_waste_records_archive_retain_until` (`retain_until`),
  KEY `idx_waste_records_archive_archived_at` (`archived_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


